fn max_subarray(xs: List[Int]) -> Option[(Int, Int, Int)] {
  if len(xs) == 0 {
    return None
  }
  var current_sum = 0
  var current_start = 0
  var best = (unwrap_or(first(xs), 0), 0, 0)
  for (i, x) in enumerate(xs) {
    if current_sum < 0 {
      current_sum = x
      current_start = i
    } else {
      current_sum = current_sum + x
    }
    if current_sum > best.0 {
      best = (current_sum, current_start, i)
    }
  }
  return Some(best)
}

