type Job {
  name: String,
  deps: List[String],
}

fn deps_placed(deps: List[String], order: List[String]) -> Bool {
  for dep in deps {
    if !contains(order, dep) {
      return false
    }
  }
  return true
}

fn build_order(jobs: List[Job]) -> Result[List[String], String] {
  let names = map(jobs, |job| job.name)
  let empty = take(names, 0)
  var seen = empty
  for name in names {
    if contains(seen, name) {
      return Err("duplicate job: " + name)
    }
    seen = append(seen, name)
  }

  for job in jobs {
    for dep in job.deps {
      if !contains(names, dep) {
        return Err("unknown dependency: " + dep)
      }
    }
  }

  var order = empty
  while len(order) < len(jobs) {
    var placed = false
    for job in jobs {
      if !contains(order, job.name) && deps_placed(job.deps, order) {
        order = append(order, job.name)
        placed = true
        break
      }
    }
    if !placed {
      return Err("cycle detected")
    }
  }
  return Ok(order)
}

