type Instr =
  | Push(n: Int)
  | Pop
  | Add
  | Sub
  | Mul
  | Dup
  | Swap
  | Jz(target: Int)
  | Jmp(target: Int)
  | Print
  | Halt

fn empty_values() -> List[Int] {
  return []
}

fn stack_needed(instr: Instr) -> Int {
  return match instr {
    Pop => 1,
    Dup => 1,
    Print => 1,
    Jz(_) => 1,
    Add => 2,
    Sub => 2,
    Mul => 2,
    Swap => 2,
    _ => 0,
  }
}

fn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {
  let code = map_from(enumerate(prog))
  let size = len(prog)
  var stack = empty_values()
  var output = empty_values()
  var pc = 0
  var steps = 0
  while pc < size {
    if steps >= 1000 {
      return Err("step limit exceeded")
    }
    steps = steps + 1
    let instr = unwrap_or(map_get(code, pc), Halt)
    if instr == Halt {
      return Ok(output)
    }
    let depth = len(stack)
    if depth < stack_needed(instr) {
      return Err("stack underflow at " + to_string(pc))
    }
    let target = match instr {
      Jz(t) => t,
      Jmp(t) => t,
      _ => pc,
    }
    if target < 0 || target >= size {
      return Err("bad jump at " + to_string(pc))
    }
    let b = unwrap_or(last(stack), 0)
    let rest = take(stack, max(0, depth - 1))
    let a = unwrap_or(last(rest), 0)
    let base = take(stack, max(0, depth - 2))
    stack = match instr {
      Push(n) => append(stack, n),
      Pop => rest,
      Add => append(base, a + b),
      Sub => append(base, a - b),
      Mul => append(base, a * b),
      Dup => append(stack, b),
      Swap => append(append(base, b), a),
      Jz(_) => rest,
      Print => rest,
      _ => stack,
    }
    if instr == Print {
      output = append(output, b)
    }
    if instr == Jmp(target) || instr == Jz(target) && b == 0 {
      pc = target
    } else {
      pc = pc + 1
    }
  }
  return Ok(output)
}

