fn row_marks(row: String) -> List[String] {
  let marks = ["X", "O", "."]
  for a in marks {
    for b in marks {
      for c in marks {
        if row == a + b + c {
          return [a, b, c]
        }
      }
    }
  }
  return []
}

fn has_line(positions: List[Int]) -> Bool {
  let lines = [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8],
    [0, 3, 6],
    [1, 4, 7],
    [2, 5, 8],
    [0, 4, 8],
    [2, 4, 6],
  ]
  for line in lines {
    let occupied = filter(line, |i| contains(positions, i))
    if len(occupied) == 3 {
      return true
    }
  }
  return false
}

fn tic_tac_toe(board: List[String]) -> String {
  if len(board) != 3 {
    return "invalid"
  }
  var xs = []
  var os = []
  for (r, row) in enumerate(board) {
    let marks = row_marks(row)
    if len(marks) != 3 {
      return "invalid"
    }
    for (c, mark) in enumerate(marks) {
      let position = 3 * r + c
      if mark == "X" {
        xs = append(xs, position)
      } else if mark == "O" {
        os = append(os, position)
      }
    }
  }
  let x_count = len(xs)
  let o_count = len(os)
  let extra_x = x_count - o_count
  if extra_x < 0 || extra_x > 1 {
    return "invalid"
  }
  let x_wins = has_line(xs)
  let o_wins = has_line(os)
  if (x_wins && o_wins) || (x_wins && extra_x != 1) || (o_wins && extra_x != 0) {
    return "invalid"
  }
  if x_wins {
    return "X wins"
  }
  if o_wins {
    return "O wins"
  }
  if x_count + o_count == 9 {
    return "draw"
  }
  return "in progress"
}

