export function k_most_frequent(xs: number[], k: number): [number, number][] {
  if (k <= 0) {
    return [];
  }

  const counts = new Map<number, number>();
  for (const value of xs) {
    counts.set(value, (counts.get(value) ?? 0) + 1);
  }

  const pairs = Array.from(counts.entries());
  pairs.sort(([valueA, countA], [valueB, countB]) => {
    if (countA !== countB) {
      return countB - countA;
    }
    if (Number.isNaN(valueA)) {
      return Number.isNaN(valueB) ? 0 : 1;
    }
    if (Number.isNaN(valueB)) {
      return -1;
    }
    return valueA < valueB ? -1 : valueA > valueB ? 1 : 0;
  });

  return pairs.slice(0, k);
}

