type Job = { name: string; deps: string[] };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function build_order(jobs: Job[]): Result<string[]> {
  const indices = new Map<string, number>();
  for (const [index, job] of jobs.entries()) {
    if (indices.has(job.name)) {
      return { ok: false, error: "duplicate job: " + job.name };
    }
    indices.set(job.name, index);
  }

  const dependents: number[][] = jobs.map(() => []);
  const remaining = jobs.map((job) => job.deps.length);
  for (const [index, job] of jobs.entries()) {
    for (const dep of job.deps) {
      const dependency = indices.get(dep);
      if (dependency === undefined) {
        return { ok: false, error: "unknown dependency: " + dep };
      }
      dependents[dependency].push(index);
    }
  }

  // A min-heap of ready jobs, ordered by their input indices.
  const ready: number[] = [];

  function enqueue(index: number): void {
    let position = ready.length;
    ready.push(index);
    while (position > 0) {
      const parent = Math.floor((position - 1) / 2);
      if (ready[parent] <= index) {
        break;
      }
      ready[position] = ready[parent];
      position = parent;
    }
    ready[position] = index;
  }

  function dequeue(): number {
    const first = ready[0];
    const last = ready.pop();
    if (last === undefined || ready.length === 0) {
      return first;
    }

    let position = 0;
    while (2 * position + 1 < ready.length) {
      const left = 2 * position + 1;
      const right = left + 1;
      const child =
        right < ready.length && ready[right] < ready[left] ? right : left;
      if (last <= ready[child]) {
        break;
      }
      ready[position] = ready[child];
      position = child;
    }
    ready[position] = last;
    return first;
  }

  for (const [index, count] of remaining.entries()) {
    if (count === 0) {
      enqueue(index);
    }
  }

