type Line = { sku: string; qty: number; unit_cents: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function floorDiv(value: bigint, divisor: bigint): bigint {
  const quotient = value / divisor;
  return value % divisor < 0n ? quotient - 1n : quotient;
}

export function invoice_total(lines: Line[], coupon: string): Result<number> {
  for (const line of lines) {
    if (line.qty < 1) {
      return { ok: false, error: "bad quantity: " + line.sku };
    }
  }

  let amount = 0n;
  for (const line of lines) {
    const lineAmount = BigInt(line.qty) * BigInt(line.unit_cents);
    amount += line.qty >= 10 ? lineAmount - floorDiv(lineAmount, 10n) : lineAmount;
  }

  switch (coupon) {
    case "":
      break;
    case "SAVE500":
      amount = amount > 500n ? amount - 500n : 0n;
      break;
    case "PCT10":
      amount -= floorDiv(amount, 10n);
      break;
    case "BIG20":
      if (amount < 10000n) {
        return { ok: false, error: "coupon not applicable: BIG20" };
      }
      amount -= floorDiv(amount, 5n);
      break;
    default:
      return { ok: false, error: "unknown coupon: " + coupon };
  }

  const tax = floorDiv(amount * 8n + 50n, 100n);
  return { ok: true, value: Number(amount + tax) };
}

