fn parse_dollars(text: String) -> Result[Int, String] {
  let groups = split(text, ",")
  if len(groups) > 1 {
    for (i, group) in enumerate(groups) {
      let width = str_len(group)
      if i == 0 {
        if width < 1 || width > 3 {
          return Err("bad dollars")
        }
      } else if width != 3 {
        return Err("bad dollars")
      }
    }
  }
  let digits = join(groups, "")
  if str_len(digits) > 15 {
    return Err("bad dollars")
  }
  let dollars = unwrap_or(parse_int(digits), -1)
  if dollars < 0 || to_string(dollars) != digits {
    return Err("bad dollars")
  }
  return Ok(dollars)
}

fn parse_money(s: String) -> Result[Int, String] {
  let dollar_parts = split(s, "$")
  let prefix = unwrap_or(first(dollar_parts), "")
  if len(dollar_parts) < 2 || (prefix != "" && prefix != "-") {
    return Err("missing $")
  }

  let body = join(drop(dollar_parts, 1), "$")
  let parts = split(body, ".")
  var cents = 0
  if len(parts) > 1 {
    let text = unwrap_or(last(parts), "")
    if len(parts) != 2 || str_len(text) != 2 {
      return Err("bad cents")
    }
    let tagged = "1" + text
    let value = unwrap_or(parse_int(tagged), -1)
    if to_string(value) != tagged {
      return Err("bad cents")
    }
    cents = value - 100
  }

  let dollars_text = unwrap_or(first(parts), "")
  let dollars = try parse_dollars(dollars_text)
  if dollars > 900719925474099 || (dollars == 900719925474099 && cents > 91) {
    return Err("bad dollars")
  }
  let total = dollars * 100 + cents
  if prefix == "-" {
    return Ok(-total)
  }
  return Ok(total)
}

