type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function parse_duration(s: string): Result<number> {
  if (s.length === 0) {
    return { ok: false, error: "empty" };
  }

  let total = 0;
  let digits = "";
  let previousMultiplier = Infinity;

  for (const ch of s) {
    if (ch >= "0" && ch <= "9") {
      digits += ch;
      continue;
    }

    let multiplier: number;
    switch (ch) {
      case "h":
        multiplier = 3600;
        break;
      case "m":
        multiplier = 60;
        break;
      case "s":
        multiplier = 1;
        break;
      default:
        return { ok: false, error: `unknown unit: ${ch}` };
    }

    if (digits.length === 0) {
      return { ok: false, error: `missing number before ${ch}` };
    }
    if (multiplier >= previousMultiplier) {
      return { ok: false, error: `unit out of order: ${ch}` };
    }

    total += Number(digits) * multiplier;
    previousMultiplier = multiplier;
    digits = "";
  }

  if (digits.length !== 0) {
    return { ok: false, error: "missing unit" };
  }
  return { ok: true, value: total };
}

