export function max_subarray(xs: number[]): [number, number, number] | null {
  if (xs.length === 0) return null;

  let runSum = xs[0];
  let runStart = 0;
  let bestSum = runSum;
  let bestStart = 0;
  let bestEnd = 0;

  for (let end = 1; end < xs.length; end++) {
    const value = xs[end];
    const extendedSum = runSum + value;

    if (value > extendedSum) {
      runSum = value;
      runStart = end;
    } else {
      runSum = extendedSum;
    }

    if (runSum > bestSum || (runSum === bestSum && runStart < bestStart)) {
      bestSum = runSum;
      bestStart = runStart;
      bestEnd = end;
    }
  }

  return [bestSum, bestStart, bestEnd];
}

