  if (!/^(?:0|[1-9][0-9]*|[1-9][0-9]{0,2}(?:,[0-9]{3})+)(?![\s\S])/.test(dollars)) {
    return { ok: false, error: "bad dollars" };
  }

  const amount = Number(dollars.replace(/,/g, "")) * 100 + cents;
  return { ok: true, value: negative ? -amount : amount };
}

