export function tic_tac_toe(board: string[]): string {
  const cells = board.join("");
  let xCount = 0;
  let oCount = 0;

  for (const cell of cells) {
    if (cell === "X") xCount++;
    if (cell === "O") oCount++;
  }

  const difference = xCount - oCount;
  if (difference !== 0 && difference !== 1) return "invalid";

  const lines = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6],
  ] as const;

  const hasLine = (mark: "X" | "O"): boolean =>
    lines.some(([a, b, c]) =>
      cells[a] === mark && cells[b] === mark && cells[c] === mark
    );

  const xWins = hasLine("X");
  const oWins = hasLine("O");

  if ((xWins && oWins) || (xWins && difference !== 1) || (oWins && difference !== 0)) {
    return "invalid";
  }

  if (xWins) return "X wins";
  if (oWins) return "O wins";
  return xCount + oCount === 9 ? "draw" : "in progress";
}

